using System.Text;
using System.Text.Json;
using RimGovernor.Brain.Policy;
using Xunit;

namespace RimGovernor.Brain.Domain.Tests;

// mechanic_cards.json (#3220) is generated by thoughtaudit -guards and embedded in Brain.Policy; these tests read the embedded copy.
public sealed class MechanicCardsTests
{
    private const string Minimal = """{"schema":2,"cards":[{"def":"D","status":"extracted","xml":{"nullifyingTraits":[],"stages":[]},"sites":[]}]}""";

    [Fact]
    public void EmbeddedSarcophagusCardCarriesItsGuardsWritersAndXml()
    {
        var card = MechanicCards.ByDef["KnowBuriedInSarcophagus"];

        Assert.Equal(MechanicCardStatus.Unreachable, card.Status);
        Assert.False(card.Live);
        Assert.Equal(4, Assert.Single(card.Xml.Stages).BaseMoodEffect);

        var site = Assert.Single(card.Sites);
        Assert.Equal("Building_Sarcophagus.Notify_HauledTo", site.Site);
        var guards = site.Guards.Take(4).Select(g => g.Expr.Op is null ? g.Expr.Decl : g.Expr.Op + " " + g.Expr.Args![0].Decl);
        Assert.Equal(["Building_Sarcophagus.thisIsFirstBodyEver", "Pawn.IsColonist", "RaceProperties.Humanlike", "not Corpse.everBuriedInSarcophagus"], guards);

        // #3242/#3243: thisIsFirstBodyEver is set only by TryAcceptThing, which no hauling caller of Notify_HauledTo runs.
        var fields = site.Writers.Concat(site.Writers.SelectMany(f => f.Follows)).ToDictionary(f => f.Field);
        foreach (var field in new[] { "Building_Sarcophagus.thisIsFirstBodyEver", "Building_Sarcophagus.everNonEmpty", "Corpse.everBuriedInSarcophagus" })
        {
            Assert.NotEmpty(fields[field].Writers);
        }
    }

    // #3281: the Gate 1 lever, generated with no hand edits.
    [Fact]
    public void EmbeddedDeadMansApparelCardCountsTaintedWornApparel()
    {
        var card = MechanicCards.ByDef["DeadMansApparel"];

        Assert.Equal([-5.0, -8, -11, -14], card.Xml.Stages.Select(s => s.BaseMoodEffect ?? 0));
        Assert.Equal(["Bloodlust"], card.Xml.NullifyingTraits);
        Assert.Equal(["Inhumanized"], card.Xml.NullifyingHediffs);
        Assert.Equal(2, card.Sites.Count);
        Assert.All(card.Sites, site =>
        {
            var guard = Assert.Single(site.Guards);
            Assert.Equal("Pawn_ApparelTracker.WornApparel", guard.Count!.Over.Decl);
            Assert.Equal("Apparel.WornByCorpse", guard.Count.Where.Decl);
        });
    }

    // #3324: ThoughtWorker_Cold/_Hot stage bands, generated with no hand table: the stage over the traced input, thresholds
    // 10/20/30 and the Temperature_Tough shift of -2 under Ideology. The native probes environment/cold and environment/hot
    // passed at the cards' drift hashes, so both ship verified and Live (#3328).
    [Theory]
    [InlineData("EnvironmentCold", "StatDefOf.ComfyTemperatureMin", 0)]
    [InlineData("EnvironmentHot", "StatDefOf.ComfyTemperatureMax", 1)]
    public void EmbeddedTemperatureCardsCarryTheirStageBand(string def, string stat, int statArg)
    {
        var card = MechanicCards.ByDef[def];

        Assert.Equal(MechanicCardStatus.Verified, card.Status);
        Assert.True(card.Live);
        Assert.Equal([-4.0, -8, -12, -16], card.Xml.Stages.Select(s => s.BaseMoodEffect ?? 0));
        var band = Assert.Single(card.Sites).Stage!;
        Assert.Equal("-", band.Input.Op);
        Assert.Equal(("stat", stat), (band.Input.Args![statArg].Kind, band.Input.Args[statArg].Decl));
        Assert.Equal("Thing.AmbientTemperature", band.Input.Args[1 - statArg].Decl);
        Assert.Equal([new MechanicCardThreshold(10, 0), new(20, 1), new(30, 2)], band.Thresholds);
        Assert.Equal(3, band.Else);
        var modifier = Assert.Single(band.Modifiers);
        Assert.Equal(-2, modifier.Delta);
        Assert.Equal(["ModsConfig.IdeologyActive", "Pawn.Ideo", "Ideo.HasPrecept", "PreceptDefOf.Temperature_Tough"], Decls(modifier.When));
    }

    private static IEnumerable<string> Decls(MechanicCardExpr e) => (e.Decl is { } d ? [d] : Array.Empty<string>()).Concat((e.Args ?? []).SelectMany(Decls));

    [Fact]
    public void MinimalFileParses() => Assert.Equal(MechanicCardStatus.Extracted, Parse(Minimal)["D"].Status);

    [Fact]
    public void UnreachableStatusParsesAndIsNeverLive()
    {
        var card = Parse(Minimal.Replace("\"extracted\"", "\"unreachable\"", StringComparison.Ordinal))["D"];

        Assert.Equal(MechanicCardStatus.Unreachable, card.Status);
        Assert.False(card.Live);
    }

    [Theory]
    [InlineData("{")]
    [InlineData("""{"schema":2}""")]
    [InlineData("""{"schema":2,"cards":[],"extra":0}""")]
    [InlineData("""{"schema":2,"cards":[{"def":"D","status":"draft","xml":{"nullifyingTraits":[],"stages":[]},"sites":[]}]}""")]
    [InlineData("""{"schema":2,"cards":[{"def":"D","status":1,"xml":{"nullifyingTraits":[],"stages":[]},"sites":[]}]}""")]
    public void MalformedFileFailsLoudly(string json) => Assert.Throws<JsonException>(() => Parse(json));

    [Fact]
    public void UnknownSchemaFailsLoudly() => Assert.Throws<DomainException>(() => Parse(Minimal.Replace("\"schema\":2", "\"schema\":1", StringComparison.Ordinal)));

    [Fact]
    public void DuplicateDefFailsLoudly() =>
        Assert.Throws<DomainException>(() => Parse(Minimal.Replace("}]}", "},{\"def\":\"D\",\"status\":\"verified\",\"xml\":{\"nullifyingTraits\":[],\"stages\":[]},\"sites\":[]}]}", StringComparison.Ordinal)));

    private static IReadOnlyDictionary<string, MechanicCard> Parse(string json) => MechanicCards.Parse(new MemoryStream(Encoding.UTF8.GetBytes(json)));
}
